import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapComponent from "../MapComponent";
import "./LandPredictionForm.css";

export default function LandPredictionForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    location: "",
    area: "",
    zoning: "",
    latitude: "",
    longitude: "",

    waterApplicable: "",
    waterDistance: "",

    roadApplicable: "",
    roadDistance: "",

    schoolApplicable: "",
    schoolDistance: "",

    railwayApplicable: "",
    railwayDistance: "",

    busApplicable: "",
    busDistance: "",
  });
  const [coordinates, setCoordinates] = useState({ lat: null, lng: null });
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const getCurrentLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          setCoordinates({ lat: latitude, lng: longitude });
          setForm((prev) => ({ ...prev, latitude, longitude }));
          const geoApiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
          try {
            const resp = await fetch(
              `https://maps.googleapis.com/maps/api/geocode/json?latlng=${latitude},${longitude}&key=${geoApiKey}`
            );
            const data = await resp.json();
            if (data.status === "OK") {
              const rooftopResult = data.results.find(
                (r) => r.geometry.location_type === "ROOFTOP"
              );
              setForm((prev) => ({
                ...prev,
                location: (rooftopResult || data.results[0]).formatted_address,
              }));
            } else {
              alert(`Failed to get address: ${data.status} - ${data.error_message || ""}`);
            }
          } catch {
            alert("Error fetching location address.");
          }
        },
        () => alert("Permission denied or unable to get location."),
        { enableHighAccuracy: true }
      );
    } else {
      alert("Geolocation unsupported in this browser.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(undefined);
    setLoading(true);
    try {
      const response = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/land`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await response.json();
      setResult(data.price);
    } catch {
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  const renderFacility = (label, applicableName, distanceName) => (
    <div className="form-group">
      <div className="facility-label">{label}</div>
      <div className="facility-radios">
        <label>
          <input
            type="radio"
            name={applicableName}
            value="applicable"
            checked={form[applicableName] === "applicable"}
            onChange={e =>
              setForm(f => ({
                ...f,
                [applicableName]: e.target.value,
                [distanceName]: "",
              }))
            }
          />
          Applicable
        </label>
        <label>
          <input
            type="radio"
            name={applicableName}
            value="notApplicable"
            checked={form[applicableName] === "notApplicable"}
            onChange={e =>
              setForm(f => ({
                ...f,
                [applicableName]: e.target.value,
                [distanceName]: "",
              }))
            }
          />
          Not Applicable
        </label>
      </div>
      {form[applicableName] === "applicable" && (
        <input
          type="number"
          min="0"
          step="0.01"
          placeholder={`Distance from ${label.toLowerCase()} (km)`}
          value={form[distanceName]}
          onChange={e => setForm(f => ({ ...f, [distanceName]: e.target.value }))}
          required
        />
      )}
    </div>
  );

  return (
    <div className="land-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="land-predict-panels">
        <div className="land-details-card">
          <div className="details-header">
            <span className="icon">
              <img src="/icons/land.png" alt="Land" />
            </span>
            <span className="details-title">Land Details</span>
          </div>
          <div className="details-desc">
            Enter the details of the land to get an accurate price prediction
          </div>

          <form onSubmit={handleSubmit} className="details-form">
            <div className="form-group">
              <label className="form-label">Location</label>
              <div className="input-with-icon">
                <span className="input-icon">📍</span>
                <input
                  name="location"
                  type="text"
                  placeholder="e.g., County, City, District"
                  value={form.location}
                  onChange={handleChange}
                  required
                />
                <button
                  type="button"
                  className="location-btn"
                  onClick={getCurrentLocation}
                >
                  Use My Location
                </button>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Choose Location on Map:</label>
              <MapComponent
                lat={coordinates.lat}
                lng={coordinates.lng}
                onLocationSelect={(lat, lng) => {
                  setCoordinates({ lat, lng });
                  setForm(f => ({ ...f, latitude: lat, longitude: lng }));
                }}
              />
              {coordinates.lat && coordinates.lng && (
                <div style={{ fontSize: "0.9em", marginTop: 4 }}>
                  Selected: {coordinates.lat}, {coordinates.lng}
                </div>
              )}
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Area (acres)</label>
                <input
                  name="area"
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="2.5"
                  value={form.area}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label">Zoning Type</label>
                <select
                  name="zoning"
                  value={form.zoning}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select zoning</option>
                  <option>Agricultural</option>
                  <option>Residential</option>
                  <option>Commercial</option>
                  <option>Industrial</option>
                  <option>Conservation</option>
                </select>
              </div>
            </div>

            {/* Additional features */}
            {renderFacility("Water Service", "waterApplicable", "waterDistance")}
            {renderFacility("Road Access", "roadApplicable", "roadDistance")}
            {renderFacility("School", "schoolApplicable", "schoolDistance")}
            {renderFacility("Railway Station", "railwayApplicable", "railwayDistance")}
            {renderFacility("Bus Stand", "busApplicable", "busDistance")}

            <button className="predict-btn" type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict Land Price"}
            </button>
          </form>
        </div>

        <div className="price-prediction-card">
          <div className="price-header">
            <span className="price-icon">₹</span>
            <span className="price-title">Price Prediction</span>
          </div>
          <div className="price-desc">Your estimated land price will appear here</div>
          <div className="price-output">
            {!!result ? (
              <div className="price-result">
                <span className="result-value">₹ {result}</span>
              </div>
            ) : (
              <div className="result-placeholder">
                <span className="result-calc-icon">🧮</span>
                <span>Fill out the form to see your price prediction</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
